import{_ as e,o as r,c as s,ak as t}from"./chunks/framework.BHDkgpnK.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/getting-started.md","filePath":"zh/guide/getting-started.md","lastUpdated":1782307719000}'),o={name:"zh/guide/getting-started.md"};function i(l,a,n,h,c,d){return r(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h2><p>KossJS 是一个高性能的嵌入式 JavaScript 运行时引擎，原生支持 HTTP/HTTPS 下载（Fetch API）和 Node.js 标准库模块。KossJS 采用 <strong>Rust 语言</strong>编写，核心逻辑编译为动态链接库 (DLL/SO/DYLIB)，可供 Python、C++、C#、TypeScript/Node.js、Java/Kotlin 等多种语言调用。</p><p>本文档将指导您如何在 Python 项目中快速集成和使用 KossJS。</p><h2 id="开源协议" tabindex="-1">开源协议 <a class="header-anchor" href="#开源协议" aria-label="Permalink to “开源协议”">​</a></h2><p>本项目采用 <a href="https://gnu.ac.cn/licenses/agpl-3.0.html" target="_blank" rel="noreferrer">GNU AGPL v3.0</a> 协议开源发布。</p><h2 id="安装指南" tabindex="-1">安装指南 <a class="header-anchor" href="#安装指南" aria-label="Permalink to “安装指南”">​</a></h2><h3 id="_1-系统要求" tabindex="-1">1. 系统要求 <a class="header-anchor" href="#_1-系统要求" aria-label="Permalink to “1. 系统要求”">​</a></h3><ul><li><strong>操作系统</strong>: Windows (x64), Linux (Ubuntu 22.04+), macOS, Android, iOS, 鸿蒙</li><li><strong>Python 版本</strong>: Python 3.11 及以上</li><li><strong>依赖项</strong>: 不需要额外安装 Python 依赖库，通过 <em><strong>ctypes</strong></em> 直接调用内核</li></ul><h3 id="_2-获取内核文件" tabindex="-1">2. 获取内核文件 <a class="header-anchor" href="#_2-获取内核文件" aria-label="Permalink to “2. 获取内核文件”">​</a></h3><p>动态链接库文件：</p><ul><li>Windows: <em><strong>kossjs.dll</strong></em></li><li>Linux: <em><strong>kossjs.so</strong></em></li><li>macOS: <em><strong>kossjs.dylib</strong></em></li></ul><h3 id="_3-获取-python-接口封装" tabindex="-1">3. 获取 Python 接口封装 <a class="header-anchor" href="#_3-获取-python-接口封装" aria-label="Permalink to “3. 获取 Python 接口封装”">​</a></h3><p>为了简化调用，官方提供了封装好的 Python 接口文件 <em><strong>kossjs_interface.py</strong></em>。</p><ol><li>下载 <em><strong>kossjs_interface.py</strong></em></li><li>将 <strong>内核文件</strong> 和 <em><strong>kossjs_interface.py</strong></em> 放置在您的 Python 项目根目录下</li></ol><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to “基本用法”">​</a></h2><h3 id="初始化与执行" tabindex="-1">初始化与执行 <a class="header-anchor" href="#初始化与执行" aria-label="Permalink to “初始化与执行”">​</a></h3><p>首先，导入模块并创建实例。</p><p>`python from kossjs_interface import KossJS</p><h1 id="_1-创建实例-stable-true-生产模式" tabindex="-1">1. 创建实例（stable=True，生产模式） <a class="header-anchor" href="#_1-创建实例-stable-true-生产模式" aria-label="Permalink to “1. 创建实例（stable=True，生产模式）”">​</a></h1><p>koss = KossJS()</p><h1 id="_2-执行-javascript-代码" tabindex="-1">2. 执行 JavaScript 代码 <a class="header-anchor" href="#_2-执行-javascript-代码" aria-label="Permalink to “2. 执行 JavaScript 代码”">​</a></h1><p>result = koss.eval(&quot;1 + 2&quot;) print(result) # 输出: 3</p><h1 id="_3-使用更复杂的代码" tabindex="-1">3. 使用更复杂的代码 <a class="header-anchor" href="#_3-使用更复杂的代码" aria-label="Permalink to “3. 使用更复杂的代码”">​</a></h1><p>code = &quot;&quot;&quot; const sum = (a, b) =&gt; a + b; sum(10, 20); &quot;&quot;&quot; result = koss.eval(code) print(result) # 输出: 30</p><h1 id="_4-设置全局变量" tabindex="-1">4. 设置全局变量 <a class="header-anchor" href="#_4-设置全局变量" aria-label="Permalink to “4. 设置全局变量”">​</a></h1><p>koss.set_global(&quot;myVar&quot;, &quot;Hello from Python&quot;) result = koss.eval(&quot;myVar&quot;) print(result) # 输出: Hello from Python</p><h1 id="_5-销毁实例" tabindex="-1">5. 销毁实例 <a class="header-anchor" href="#_5-销毁实例" aria-label="Permalink to “5. 销毁实例”">​</a></h1><p>koss.destroy() `</p><h3 id="使用-fetch-api" tabindex="-1">使用 Fetch API <a class="header-anchor" href="#使用-fetch-api" aria-label="Permalink to “使用 Fetch API”">​</a></h3><p>KossJS 内置了原生 Fetch API 支持。异步代码使用 un_async() 执行：</p><p>`python from kossjs_interface import KossJS</p><p>koss = KossJS()</p><h1 id="使用-run-async-处理异步-fetch" tabindex="-1">使用 run_async() 处理异步 fetch <a class="header-anchor" href="#使用-run-async-处理异步-fetch" aria-label="Permalink to “使用 run_async() 处理异步 fetch”">​</a></h1><p>result = koss.run_async(&#39;&#39;&#39; (async () =&gt; { try { const response = await fetch(&quot;<a href="https://jsonplaceholder.typicode.com/todos/1" target="_blank" rel="noreferrer">https://jsonplaceholder.typicode.com/todos/1</a>&quot;); const data = await response.json(); return JSON.stringify(data); } catch (error) { return &quot;Error: &quot; + error.message; } })(); &#39;&#39;&#39;, timeout_ms=30000) print(result)</p><p>koss.destroy() `</p><h3 id="运行-javascript-文件" tabindex="-1">运行 JavaScript 文件 <a class="header-anchor" href="#运行-javascript-文件" aria-label="Permalink to “运行 JavaScript 文件”">​</a></h3><p>`python from kossjs_interface import KossJS</p><p>koss = KossJS()</p><h1 id="运行-js-文件" tabindex="-1">运行 .js 文件 <a class="header-anchor" href="#运行-js-文件" aria-label="Permalink to “运行 .js 文件”">​</a></h1><p>result = koss.run_file(&quot;./script.js&quot;) print(result)</p><h1 id="运行-es-module-文件" tabindex="-1">运行 ES Module 文件 <a class="header-anchor" href="#运行-es-module-文件" aria-label="Permalink to “运行 ES Module 文件”">​</a></h1><p>result = koss.run_module(&quot;./module.mjs&quot;) print(result)</p><p>koss.destroy() `</p><h3 id="注册-native-函数" tabindex="-1">注册 Native 函数 <a class="header-anchor" href="#注册-native-函数" aria-label="Permalink to “注册 Native 函数”">​</a></h3><p>可以将 Python 函数注册为 JavaScript 可调用的函数：</p><p>`python from kossjs_interface import KossJS, JsError</p><p>def add(a, b): return str(int(a) + int(b))</p><p>koss = KossJS()</p><h1 id="注册-python-函数" tabindex="-1">注册 Python 函数 <a class="header-anchor" href="#注册-python-函数" aria-label="Permalink to “注册 Python 函数”">​</a></h1><p>koss.register_function(&quot;add&quot;, add)</p><h1 id="在-javascript-中调用" tabindex="-1">在 JavaScript 中调用 <a class="header-anchor" href="#在-javascript-中调用" aria-label="Permalink to “在 JavaScript 中调用”">​</a></h1><p>result = koss.eval(&quot;add(10, 20)&quot;) print(result) # 输出: 30</p><p>koss.destroy() `</p><h3 id="使用上下文管理器" tabindex="-1">使用上下文管理器 <a class="header-anchor" href="#使用上下文管理器" aria-label="Permalink to “使用上下文管理器”">​</a></h3><p>`python from kossjs_interface import KossJS</p><h1 id="使用上下文管理器自动管理资源" tabindex="-1">使用上下文管理器自动管理资源 <a class="header-anchor" href="#使用上下文管理器自动管理资源" aria-label="Permalink to “使用上下文管理器自动管理资源”">​</a></h1><p>with KossJS() as koss: result = koss.eval(&quot;&#39;Hello &#39; + &#39;World&#39;&quot;) print(result) # 输出: Hello World</p><h1 id="自动销毁" tabindex="-1">自动销毁 <a class="header-anchor" href="#自动销毁" aria-label="Permalink to “自动销毁”">​</a></h1><p>`</p><h2 id="kossjs-的特性" tabindex="-1">KossJS 的特性 <a class="header-anchor" href="#kossjs-的特性" aria-label="Permalink to “KossJS 的特性”">​</a></h2><h3 id="安全与沙箱" tabindex="-1">安全与沙箱 <a class="header-anchor" href="#安全与沙箱" aria-label="Permalink to “安全与沙箱”">​</a></h3><p>KossJS 支持通过 28 个细粒度能力位精确控制实例权限，以及三层安全机制（能力位 + 审核掩码 + 审核回调）：</p><p>`python from kossjs_interface import KossJS</p><h1 id="沙箱模式-纯计算-禁止所有-io" tabindex="-1">沙箱模式：纯计算，禁止所有 IO <a class="header-anchor" href="#沙箱模式-纯计算-禁止所有-io" aria-label="Permalink to “沙箱模式：纯计算，禁止所有 IO”">​</a></h1><p>with KossJS(capabilities=KossJS.KOSS_CAP_SANDBOX) as koss: result = koss.eval(&quot;1 + 1&quot;) print(result) # 正常工作</p><h1 id="只允许网络-加密" tabindex="-1">只允许网络 + 加密 <a class="header-anchor" href="#只允许网络-加密" aria-label="Permalink to “只允许网络 + 加密”">​</a></h1><p>with KossJS(capabilities=KossJS.KOSS_CAP_ALL_NET | KossJS.KOSS_CAP_ALL_CRYPTO) as koss: result = koss.run_async(&#39;&#39;&#39; (async () =&gt; { const r = await fetch(&quot;<a href="https://api.github.com/users/github" target="_blank" rel="noreferrer">https://api.github.com/users/github</a>&quot;); const d = await r.json(); return d.login; })(); &#39;&#39;&#39;) `</p><h3 id="稳定模式-stable" tabindex="-1">稳定模式（stable） <a class="header-anchor" href="#稳定模式-stable" aria-label="Permalink to “稳定模式（stable）”">​</a></h3><p>stable 参数控制实例的生产就绪模式：</p><p>`python from kossjs_interface import KossJS</p><h1 id="生产模式-默认-禁用-ffi-和-worker" tabindex="-1">生产模式（默认，禁用 FFI 和 Worker） <a class="header-anchor" href="#生产模式-默认-禁用-ffi-和-worker" aria-label="Permalink to “生产模式（默认，禁用 FFI 和 Worker）”">​</a></h1><p>koss = KossJS() print(koss.is_stable) # True</p><h1 id="开发模式-启用所有功能" tabindex="-1">开发模式（启用所有功能） <a class="header-anchor" href="#开发模式-启用所有功能" aria-label="Permalink to “开发模式（启用所有功能）”">​</a></h1><p>koss_dev = KossJS(stable=False) print(koss_dev.is_stable) # False `</p><p>详见 <a href="/KossJS/zh/security-sandbox/security-sandbox.html">安全与沙箱指南</a>。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>stable 模式下 FFI 和 Worker 被禁用？查看 <a href="/KossJS/zh/reference/stable-alternatives.html">stable 模式替代方案</a> 了解如何在生产环境中实现相同功能。</p></div><h3 id="高性能" tabindex="-1">高性能 <a class="header-anchor" href="#高性能" aria-label="Permalink to “高性能”">​</a></h3><ul><li><strong>Rust 实现</strong>：极低的内存占用</li><li><strong>极短 GC 停顿</strong>：Rust 侧无 GC，JS 引擎 GC 停顿极短</li><li><strong>快速启动</strong>：实例创建开销极低</li></ul><h3 id="完整-js-支持" tabindex="-1">完整 JS 支持 <a class="header-anchor" href="#完整-js-支持" aria-label="Permalink to “完整 JS 支持”">​</a></h3><ul><li><strong>ES2022</strong>：最新的 ECMAScript 支持</li><li><strong>ES Modules</strong>：原生 import/export 支持</li><li><strong>Async/Await</strong>：异步编程支持</li></ul><h3 id="内置模块" tabindex="-1">内置模块 <a class="header-anchor" href="#内置模块" aria-label="Permalink to “内置模块”">​</a></h3><ul><li><strong>Fetch API</strong>：原生 HTTP 请求</li><li><strong>Node.js 兼容</strong>：标准库模块（assert、buffer、crypto、events、http、net、stream、url、zlib 等）</li><li><strong>Buffer</strong>：Node.js 兼容的 Buffer 实现</li><li><strong>Path/URL/Querystring</strong>：完整的路径和 URL 处理</li></ul><h3 id="ffi-foreign-function-interface" tabindex="-1">FFI（Foreign Function Interface） <a class="header-anchor" href="#ffi-foreign-function-interface" aria-label="Permalink to “FFI（Foreign Function Interface）”">​</a></h3><ul><li><strong>Senri FFI</strong>：从 JS 调用 native C 库</li><li><strong>N-API 兼容</strong>：加载 .node 原生插件</li><li><strong>process.dlopen</strong>：动态库加载</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li>了解 <a href="/KossJS/zh/api/API-overview.html">API 详解</a> 以掌握更多高级功能</li><li><a href="/KossJS/zh/security-sandbox/security-sandbox.html">安全与沙箱指南</a> 了解权限控制</li><li><a href="/KossJS/zh/interface/py/how-to-use.html">Python 接口使用</a> - Python 开发指南</li></ul>',87)])])}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
